import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';

function rootForLstat(root) {
  if (typeof root !== 'string' || root.length === 0) throw Error('root must be a path');
  const rootLength = path.parse(root).root.length;
  let end = root.length;
  const isSeparator = process.platform === 'win32'
    ? character => character === '/' || character === '\\'
    : character => character === '/';
  while (end > rootLength && isSeparator(root[end - 1])) end--;
  return root.slice(0, end);
}
function validateRoot(root) {
  const stat = fs.lstatSync(rootForLstat(root));
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw Error('root must be a non-symlink directory');
}
function validatePath(selected) {
  if (typeof selected !== 'string' || !selected || selected.startsWith('/')
    || selected.includes('\\') || selected.includes('\0')
    || selected.split('/').some(part => !part || part === '.' || part === '..')) throw Error('invalid selected path');
}
function inspect(root, selected) {
  const parts = selected.split('/'); let current = root;
  for (let i = 0; i < parts.length; i++) {
    current = path.join(current, parts[i]);
    let stat;
    try { stat = fs.lstatSync(current); }
    catch (error) { if (error.code === 'ENOENT') return {kind:'missing'}; throw error; }
    if (stat.isSymbolicLink() || (i === parts.length - 1 ? !stat.isFile() : !stat.isDirectory())) return {kind:'unsafe'};
    if (i === parts.length - 1) {
      const bytes = fs.readFileSync(current);
      return {kind:'file',sha256:crypto.createHash('sha256').update(bytes).digest('hex'),size:bytes.length,mode:stat.mode & 0o777};
    }
  }
}
function validatedManifestFiles(manifest) {
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)
    || manifest.version !== 1 || !Array.isArray(manifest.files)) throw Error('invalid manifest');
  const seen = new Set();
  for (const entry of manifest.files) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) throw Error('invalid manifest entry');
    validatePath(entry.path);
    if (seen.has(entry.path)) throw Error('duplicate manifest path');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(entry.sha256)
      || !Number.isSafeInteger(entry.size) || entry.size < 0
      || !Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) throw Error('invalid manifest entry');
  }
  return [...manifest.files].sort((left, right) => left.path < right.path ? -1 : left.path > right.path ? 1 : 0);
}
export function createManifest(root, paths) {
  validateRoot(root);
  if (!Array.isArray(paths)) throw Error('paths must be an array');
  const seen = new Set();
  for (const selected of paths) {
    validatePath(selected);
    if (seen.has(selected)) throw Error('duplicate selection');
    seen.add(selected);
  }
  return {version:1,files:[...paths].sort().map(selected => {
    const current = inspect(root, selected);
    if (current.kind !== 'file') throw Error(`${current.kind} selected path`);
    return {path:selected,sha256:current.sha256,size:current.size,mode:current.mode};
  })};
}
export function verifyManifest(root, manifest) {
  validateRoot(root);
  const files = validatedManifestFiles(manifest);
  const report = {ok:true,unchanged:[],changed:[],missing:[],unsafe:[]};
  for (const expected of files) {
    const current = inspect(root, expected.path);
    if (current.kind === 'missing') report.missing.push(expected.path);
    else if (current.kind === 'unsafe') report.unsafe.push(expected.path);
    else {
      const reasons = [];
      if (current.sha256 !== expected.sha256 || current.size !== expected.size) reasons.push('content');
      if (current.mode !== expected.mode) reasons.push('mode');
      if (reasons.length) report.changed.push({path:expected.path,reasons});
      else report.unchanged.push(expected.path);
    }
  }
  report.ok = report.changed.length === 0 && report.missing.length === 0 && report.unsafe.length === 0;
  return report;
}

function runCli(argv) {
  const [command, ...args] = argv;
  if (command === 'create' && args.length >= 1) return {value:createManifest(args[0], args.slice(1)),code:0};
  if (command === 'verify' && args.length === 2) {
    const manifest = JSON.parse(fs.readFileSync(args[1], 'utf8'));
    const value = verifyManifest(args[0], manifest);
    return {value,code:value.ok ? 0 : 1};
  }
  throw Error('usage: snapshot.js create ROOT [PATH ...] | snapshot.js verify ROOT MANIFEST_FILE');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  try {
    const result = runCli(process.argv.slice(2));
    process.stdout.write(`${JSON.stringify(result.value)}\n`);
    process.exitCode = result.code;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`${message || 'snapshot error'}\n`);
    process.exitCode = 2;
  }
}

