import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createManifest, verifyManifest} from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));

function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-milestone-'));
  t.after(() => fs.rmSync(root, {recursive: true, force: true}));
  return root;
}

function writeSelected(root, selected, contents = selected) {
  const target = path.join(root, selected);
  fs.mkdirSync(path.dirname(target), {recursive: true});
  fs.writeFileSync(target, contents);
}

function runCli(args) {
  return spawnSync(process.execPath, [script, ...args], {encoding: 'utf8'});
}

function assertCliError(result) {
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.notEqual(result.stderr, '');
}

test('manifest SHA-256 is exactly 64 lowercase hexadecimal characters', t => {
  const root = fixture(t);
  writeSelected(root, 'file', 'contents');
  const entry = createManifest(root, ['file']).files[0];

  assert.equal(verifyManifest(root, {version: 1, files: [{...entry}]}).ok, true);
  for (const suffix of ['\n', '\r', '\r\n', '\u2028', '\u2029']) {
    const manifest = {version: 1, files: [{...entry, sha256: entry.sha256 + suffix}]};
    assert.throws(() => verifyManifest(root, manifest));
  }
});

test('unsorted manifest input produces sorted outputs without mutation', t => {
  const root = fixture(t);
  const paths = [
    'z-unchanged', 'y-unchanged', 'c-changed', 'a-changed',
    'd-missing', 'b-missing', 'g-unsafe', 'e-unsafe',
  ];
  for (const selected of paths) writeSelected(root, selected);
  const built = createManifest(root, paths);
  const byPath = new Map(built.files.map(entry => [entry.path, entry]));
  const inputOrder = ['g-unsafe', 'z-unchanged', 'd-missing', 'a-changed',
    'e-unsafe', 'y-unchanged', 'b-missing', 'c-changed'];
  const manifest = {version: 1, files: inputOrder.map(selected => byPath.get(selected))};
  const before = structuredClone(manifest);

  fs.writeFileSync(path.join(root, 'a-changed'), 'new a');
  fs.writeFileSync(path.join(root, 'c-changed'), 'new c');
  fs.unlinkSync(path.join(root, 'b-missing'));
  fs.unlinkSync(path.join(root, 'd-missing'));
  fs.unlinkSync(path.join(root, 'e-unsafe'));
  fs.mkdirSync(path.join(root, 'e-unsafe'));
  fs.unlinkSync(path.join(root, 'g-unsafe'));
  fs.mkdirSync(path.join(root, 'g-unsafe'));

  assert.deepEqual(verifyManifest(root, manifest), {
    ok: false,
    unchanged: ['y-unchanged', 'z-unchanged'],
    changed: [
      {path: 'a-changed', reasons: ['content']},
      {path: 'c-changed', reasons: ['content']},
    ],
    missing: ['b-missing', 'd-missing'],
    unsafe: ['e-unsafe', 'g-unsafe'],
  });
  assert.deepEqual(manifest, before);
});

test('CLI rejects invalid inputs with status 2, stderr, and no stdout', t => {
  const root = fixture(t);
  writeSelected(root, 'file');
  const manifestFile = path.join(root, 'manifest.json');
  fs.writeFileSync(manifestFile, JSON.stringify(createManifest(root, ['file'])));
  const invalidManifestFile = path.join(root, 'invalid.json');
  fs.writeFileSync(invalidManifestFile, JSON.stringify({version: 2, files: []}));
  const nonexistent = path.join(root, 'does-not-exist');

  for (const args of [
    ['verify', root, invalidManifestFile],
    ['verify', root, nonexistent],
    ['verify', nonexistent, manifestFile],
    ['verify', root, manifestFile, 'extra'],
  ]) assertCliError(runCli(args));
});

