function rootForLstat(root) {
  if (typeof root !== 'string' || root.length === 0) throw Error('root must be a path');
  const rootLength = path.parse(root).root.length;
  let end = root.length;
  const isSeparator = process.platform === 'win32'
    ? character => character === '/' || character === '\\'
    : character => character === '/';
  while (end > rootLength && isSeparator(root[end - 1])) end--;
  return root.slice(0, end);
}
function validateRoot(root) {
