import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {pathToFileURL} from 'node:url';
import {createManifest, verifyManifest} from '../snapshot.js';

const script = path.resolve('snapshot.js');
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extra-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function file(root, selected, contents = selected, mode = 0o640) {
  const target = path.join(root, ...selected.split('/'));
  fs.mkdirSync(path.dirname(target), {recursive:true});
  fs.writeFileSync(target, contents);
  fs.chmodSync(target, mode);
}
function cli(args) { return spawnSync(process.execPath, [script, ...args], {encoding:'utf8'}); }

test('empty manifests, JS sorting, unusual names, frozen inputs, and unselected files', t => {
  const root = fixture(t);
  const names = ['z', 'A', 'é', '😀', 'space name', 'tab\tname', 'line\nname'];
  for (const name of names) file(root, name);
  file(root, 'ignored');
  const selections = Object.freeze([...names]);
  const manifest = createManifest(root, selections);
  assert.deepEqual(manifest.files.map(entry => entry.path), [...names].sort());
  for (const entry of manifest.files) Object.freeze(entry);
  Object.freeze(manifest.files); Object.freeze(manifest);
  assert.equal(verifyManifest(root, manifest).ok, true);
  fs.writeFileSync(path.join(root, 'ignored'), 'changed');
  assert.equal(verifyManifest(root, manifest).ok, true);
  assert.deepEqual(createManifest(root, []), {version:1, files:[]});
  assert.deepEqual(verifyManifest(root, Object.freeze({version:1, files:Object.freeze([])})),
    {ok:true, unchanged:[], changed:[], missing:[], unsafe:[]});
});

test('selection and manifest validation is complete and strict', t => {
  const root = fixture(t); file(root, 'a');
  for (const value of [null, {}, 'a']) assert.throws(() => createManifest(root, value));
  for (const selected of ['', '/a', 'a\\b', 'a\0b', 'a//b', './a', 'a/.', '../a', 'a/..', 1])
    assert.throws(() => createManifest(root, [selected]));
  assert.throws(() => createManifest(root, ['a', 'a']));
  const good = createManifest(root, ['a']).files[0];
  const invalid = [null, [], {}, {version:2,files:[]}, {version:1},
    {version:1,files:[null]}, {version:1,files:[[good]]},
    {version:1,files:[{...good,path:'../x'}]},
    {version:1,files:[good,{...good}]},
    {version:1,files:[{...good,sha256:'A'.repeat(64)}]},
    {version:1,files:[{...good,sha256:'0'.repeat(63)}]},
    {version:1,files:[{...good,size:-1}]},
    {version:1,files:[{...good,size:Number.MAX_SAFE_INTEGER + 1}]},
    {version:1,files:[{...good,mode:512}]},
    {version:1,files:[{...good,mode:1.5}]}];
  for (const manifest of invalid) assert.throws(() => verifyManifest(root, manifest));
  const missingFirst = {...good,path:'missing'};
  assert.throws(() => verifyManifest(root, {version:1,files:[missingFirst,{...good,mode:999}]}));
  assert.equal(verifyManifest(root, {version:1,files:[{...good,extra:true}],extra:true}).ok, true);
});

test('reports every drift category, ordered reasons, and sorted paths', t => {
  const root = fixture(t);
  const names = ['unchanged','both','mode','size-only','missing/child','mid-file/child','mid-link/child','final-link','final-dir'];
  for (const name of names) file(root, name, 'same', 0o640);
  const manifest = createManifest(root, names);
  fs.writeFileSync(path.join(root, 'both'), 'different'); fs.chmodSync(path.join(root, 'both'), 0o600);
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  const sizeEntry = manifest.files.find(entry => entry.path === 'size-only'); sizeEntry.size++;
  fs.rmSync(path.join(root, 'missing'), {recursive:true});
  fs.rmSync(path.join(root, 'mid-file'), {recursive:true}); file(root, 'mid-file', 'x');
  fs.rmSync(path.join(root, 'mid-link'), {recursive:true}); fs.symlinkSync(root, path.join(root, 'mid-link'));
  fs.unlinkSync(path.join(root, 'final-link')); fs.symlinkSync(path.join(root, 'unchanged'), path.join(root, 'final-link'));
  fs.unlinkSync(path.join(root, 'final-dir')); fs.mkdirSync(path.join(root, 'final-dir'));
  const report = verifyManifest(root, manifest);
  assert.deepEqual(report, {ok:false, unchanged:['unchanged'], changed:[
    {path:'both',reasons:['content','mode']}, {path:'mode',reasons:['mode']}, {path:'size-only',reasons:['content']}
  ], missing:['missing/child'], unsafe:['final-dir','final-link','mid-file/child','mid-link/child']});
});

test('create rejects unsafe components and roots including trailing-separator symlinks', t => {
  const root = fixture(t); file(root, 'target/file');
  fs.symlinkSync(path.join(root, 'target'), path.join(root, 'link'));
  assert.throws(() => createManifest(root, ['link/file']));
  assert.throws(() => createManifest(root, ['target']));
  const rootLink = `${root}-link`; fs.symlinkSync(root, rootLink); t.after(() => fs.rmSync(rootLink, {force:true}));
  assert.throws(() => createManifest(`${rootLink}${path.sep}`, []));
  assert.throws(() => verifyManifest(path.join(root, 'target', 'file'), {version:1,files:[]}));
  assert.throws(() => verifyManifest(path.join(root, 'absent'), {version:1,files:[]}));
});

test('CLI create, clean verify, drift, errors, and import silence', t => {
  const root = fixture(t); file(root, 'a', 'abc');
  let result = cli(['create', root, 'a']);
  assert.equal(result.status, 0); assert.equal(result.stderr, '');
  const manifest = JSON.parse(result.stdout); assert.equal(result.stdout, `${JSON.stringify(manifest)}\n`);
  const manifestFile = path.join(root, 'manifest.json'); fs.writeFileSync(manifestFile, JSON.stringify(manifest));
  result = cli(['verify', root, manifestFile]);
  assert.equal(result.status, 0); assert.equal(result.stderr, ''); assert.equal(JSON.parse(result.stdout).ok, true);
  fs.writeFileSync(path.join(root, 'a'), 'changed');
  result = cli(['verify', root, manifestFile]);
  assert.equal(result.status, 1); assert.equal(result.stderr, ''); assert.equal(JSON.parse(result.stdout).ok, false);
  for (const args of [[], ['create'], ['verify',root], ['bogus',root], ['create',root,'../x']]) {
    result = cli(args); assert.equal(result.status, 2); assert.equal(result.stdout, ''); assert.notEqual(result.stderr, '');
  }
  fs.writeFileSync(manifestFile, '{bad'); result = cli(['verify',root,manifestFile]);
  assert.equal(result.status, 2); assert.equal(result.stdout, ''); assert.notEqual(result.stderr, '');
  result = spawnSync(process.execPath, ['--input-type=module','-e',`import(${JSON.stringify(pathToFileURL(script).href)})`], {encoding:'utf8'});
  assert.equal(result.status, 0); assert.equal(result.stdout, ''); assert.equal(result.stderr, '');
});

